import openpyxl, json
ip='/tmp/llm_rollout_qv2plk9p/mimotable_batch1_0319_template_2195_input.xlsx'
fp='/tmp/llm_rollout_qv2plk9p/mimotable_batch1_0319_template_2195_input_filled.xlsx'
jp='/mnt/hhq/data/data_pipeline/generated_tasks/route_b_mimotable_batch1/passed/template/mimotable_batch1_0319_template_2195.json'
d=json.load(open(jp))
ans=set(d['answer_position'])
iwb=openpyxl.load_workbook(ip)
fwb=openpyxl.load_workbook(fp)
extra=[]
missing=[]
for idx,iws in enumerate(iwb.worksheets):
    fws=fwb.worksheets[idx]
    for row in iws.iter_rows():
        for ic in row:
            fc=fws[ic.coordinate]
            key=f'{iws.title}!{ic.coordinate}'
            if ic.value != fc.value:
                if key in ans:
                    pass
                else:
                    extra.append((key,repr(ic.value),repr(fc.value)))
            if ic.style_id!=fc.style_id or ic.number_format!=fc.number_format:
                missing.append((key,'style',ic.style_id,fc.style_id,ic.number_format,fc.number_format))
print('unexpected value changes:',len(extra))
for e in extra[:20]:print(e)
print('style changes:',len(missing))
for e in missing[:10]:print(e)
# check all formulas unchanged
fcount=0
for row in fwb['淘宝客推广效果汇总日报表'].iter_rows():
    for c in row:
        if isinstance(c.value,str) and c.value.startswith('='):
            fcount+=1
print('formula count sheet1',fcount)
